", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分步不连续导致计算错误"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "分类分步的关键是\"不重不漏\"。分类要互斥穷尽，分步要连续独立。"}]}]}]}$$ AS jsonb), NULL, '数量关系-排列组合-分类分步的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "排列组合", "分类分步"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_case_step", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
